static inline void
pair_coalescence_count(tsk_size_t num_set_indexes, const tsk_id_t *set_indexes,
    tsk_size_t num_sample_sets, const double *parent_count, const double *child_count,
    const double *parent_state, const double *inside, double *outside, double *result)
{
    tsk_size_t i;
    tsk_id_t j, k;
    for (i = 0; i < num_sample_sets; i++) {
        outside[i] = parent_count[i] - child_count[i] - parent_state[i];
    }
    for (i = 0; i < num_set_indexes; i++) {
        j = set_indexes[2 * i];
        k = set_indexes[2 * i + 1];
        result[i] = outside[j] * inside[k];
        if (j != k) {
            result[i] += outside[k] * inside[j];
        }
    }
}

/* Number of pairs of samples that could possibly coalesce, given the number of
 * samples per set that are not missing (e.g. not isolated) in a given tree.
 * With the total number of samples per set as input, this is the total number
 * of pairs per index. */
static inline void
pair_coalescence_pairs(tsk_size_t num_set_indexes, const tsk_id_t *set_indexes,
    const double *sample_count, double *result)
{
    tsk_size_t i;
    tsk_id_t j, k;
    for (i = 0; i < num_set_indexes; i++) {
        j = set_indexes[2 * i];
        k = set_indexes[2 * i + 1];
        result[i] = sample_count[j] * sample_count[k];
        if (j == k) {
            result[i] -= sample_count[k];
            result[i] /= 2;
        }
    }
}

/* A sample is missing from a tree if it is isolated, e.g. has neither parent
 * nor children (see the "missing data" section of the data model docs). Pairs
 * involving a missing sample are not observable, so the sequence over which
 * they are missing is excluded when normalising by span. */
static inline bool
pair_coalescence_isolated(
    tsk_id_t u, const tsk_id_t *nodes_parent, const tsk_size_t *nodes_num_children)
{
    return nodes_parent[u] == TSK_NULL && nodes_num_children[u] == 0;
}

