     ```c
     /* The empirical CDF of pair coalescence times is accumulated over trees and
      * normalised by the total weight, so that "all pairs have coalesced" is only
      * exact up to floating point error: use a small tolerance when checking
      * whether the remaining, uncoalesced proportion of pairs is zero. */
     #define PAIR_COALESCENCE_TOL 1e-10

     static int
     pair_coalescence_rates(tsk_size_t input_dim, const double *weight, const double *values,
         tsk_size_t output_dim, double *output, void *params)
     {
         int ret = 0;
         double uncoalesced, rate, waiting_time, a, b;
         double *time_windows = (double *) params;
         tsk_id_t i;
         tsk_bug_assert(input_dim == output_dim);
         uncoalesced = 1.0;
         for (i = 0; i < (tsk_id_t) output_dim; i++) {
             a = time_windows[i];
             b = time_windows[i + 1];
             if (tsk_isnan(weight[i])) {
                 /* the empirical distribution is undefined, e.g. because the window
                  * contains no non-missing sequence */
                 output[i] = NAN;
                 continue;
             }
             if (uncoalesced <= PAIR_COALESCENCE_TOL) {
                 /* all pairs have coalesced by the start of the window */
                 output[i] = NAN;
                 continue;
             }
             if (weight[i] >= uncoalesced - PAIR_COALESCENCE_TOL) {
                 /* the last coalescence event is within the window, e.g. ecdf(b) is
                  * one, so use the mean waiting time until coalescence instead */
                 waiting_time = values[i] < a ? 0.0 : values[i] - a;
                 rate = 1 / waiting_time;
             } else {
                 rate = log(1 - weight[i] / uncoalesced) / (a - b);
             }
             output[i] = rate > 0 ? rate : 0;
             uncoalesced -= weight[i];
         }
         return ret;
     }
     ```
